Deque<Character> stack = new ArrayDeque<>();
String expr = "(a[b]{c})";
boolean ok = true;
for (char c : expr.toCharArray()) {
    if ("([{".indexOf(c) >= 0) stack.push(c);
    else if (")]}".indexOf(c) >= 0) {
        if (stack.isEmpty() || "([{".indexOf(stack.pop()) != ")]}".indexOf(c)) ok = false;
    }
}
System.out.println(ok && stack.isEmpty());

